function dialogForm(title,content) {return `<div class="life-overlay"><section class="life-editor" role="dialog" aria-modal="true" aria-labelledby="life-editor-title"><header><h3 id="life-editor-title">${t(title)}</h3>${button('edit-close','关闭','close')}</header><p class="life-editor-feedback" role="alert"></p>${content}</section></div>`;}

